-- Disposable PostgreSQL only. No production credentials, accounts or data are used.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE TABLE public.technical_automation_settings(enabled boolean);
INSERT INTO public.technical_automation_settings VALUES(true);
CREATE FUNCTION public.technical_automation_enabled() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT enabled FROM public.technical_automation_settings LIMIT 1 $$;
CREATE FUNCTION public.forbid_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'immutable'; END $$;
CREATE TABLE public.technical_execution_operations(id uuid PRIMARY KEY,operation_kind text,executor_kind text,executor_label text,environment text,source_ref text,source_hash text,requested_by text,payload_fingerprint text,status text,result jsonb,started_at timestamptz,UNIQUE(operation_kind,source_hash));
CREATE TABLE public.technical_execution_targets(operation_id uuid REFERENCES public.technical_execution_operations,target_table text,target_id text,PRIMARY KEY(operation_id,target_table,target_id));
CREATE TABLE public.institutional_schools(id text PRIMARY KEY);
CREATE TABLE public.test_school_markers(school_id text PRIMARY KEY REFERENCES public.institutional_schools);
CREATE TABLE public.institutional_school_identifiers(id integer PRIMARY KEY,school_id text REFERENCES public.institutional_schools,identifier_kind text,value text);
CREATE TABLE public.institutional_school_record_versions(id integer PRIMARY KEY,school_id text REFERENCES public.institutional_schools);
CREATE TABLE public.institutional_students(id text PRIMARY KEY);
CREATE TABLE public.institutional_persons(id uuid PRIMARY KEY);
CREATE TABLE public.institutional_student_persons(student_id text PRIMARY KEY REFERENCES public.institutional_students,person_id uuid REFERENCES public.institutional_persons);
CREATE TABLE public.school_enrollments(id integer PRIMARY KEY,school_id text REFERENCES public.institutional_schools,student_id text REFERENCES public.institutional_students,technical_operation_id uuid REFERENCES public.technical_execution_operations);
CREATE TABLE public.institutional_classes(id text PRIMARY KEY,school_id text REFERENCES public.institutional_schools);
CREATE TABLE public.institutional_engagements(id uuid PRIMARY KEY,person_id uuid REFERENCES public.institutional_persons,school_id text REFERENCES public.institutional_schools);
CREATE TABLE public.staff_administrative_records(id integer PRIMARY KEY,school_id text REFERENCES public.institutional_schools,source_kind text,source_file text);
CREATE TABLE public.professional_census_declarations(id integer PRIMARY KEY,person_id uuid REFERENCES public.institutional_persons,school_id text REFERENCES public.institutional_schools,technical_operation_id uuid REFERENCES public.technical_execution_operations);
CREATE TABLE public.professional_functional_links(id integer PRIMARY KEY,logical_id uuid,person_id uuid REFERENCES public.institutional_persons,originating_act_ref text,functional_registration text);
CREATE TABLE public.institutional_sector_principals(id uuid PRIMARY KEY,school_id text REFERENCES public.institutional_schools);
CREATE TABLE public.institutional_sector_provisioning_events(id integer PRIMARY KEY,principal_id uuid REFERENCES public.institutional_sector_principals);
